-- Schema-Abbild der Produktiv-DB (Supabase "Karma Food"), Stand 03.11.26. Nur Struktur, keine Daten.
-- nextval()-Defaults werden von build_schema.py in Identity-Spalten umgewandelt.
create table public.allergene_rezepturen (id bigint not null generated by default as identity, gericht text not null, zutaten text, allergene_codes text[], aktualisiert_am timestamp with time zone default now(), verantwortlich text, zkey text, crew_bestaetigt boolean default false);
create table public.app_feedback (id bigint not null generated by default as identity, store_id text, text text not null, kategorie text, bearbeitet boolean not null default false, created_at timestamp with time zone not null default now());
create table public.articles (id integer not null generated by default as identity, category text not null, name text not null, unit text not null, min_stock integer default 4, sort_order integer default 0, image_url text, verfuegbar boolean default true, verfuegbar_hinweis text, verfuegbar_bis date, lieferant text, kuechenlager_bestand numeric, bestand_stabil boolean default false, bestand_stabil_am timestamp with time zone, archiviert boolean default false, kuechenlager_notiz text);
create table public.artikel_freigaben (article_id integer not null, store_id text not null, freigegeben_am timestamp with time zone not null default now());
create table public.beilagen_reviewed (id bigint not null generated by default as identity, store_id text not null, review_date date not null, reviewed_at timestamp with time zone default now());
create table public.calendar_events (id integer not null generated by default as identity, event_date date not null, end_date date, event_type text not null, label text not null, store_id text, created_at timestamp with time zone default now());
create table public.caterings (id bigint not null generated by default as identity, datum date not null, kunde text not null, ort text, ankunft text, kontakt text, personen integer, hinweis text, menue jsonb not null default '[]'::jsonb, extras jsonb not null default '[]'::jsonb, packliste jsonb not null default '[]'::jsonb, status text not null default 'aktiv'::text, created_by text, created_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now());
create table public.checklist_done (id integer not null generated by default as identity, store_id text, template_id integer, done_date date not null default CURRENT_DATE, done_at timestamp with time zone default now());
create table public.checklist_templates (id integer not null generated by default as identity, list_type text not null, section text not null, item_text text not null, sort_order integer default 0);
create table public.dienstplan_eintraege (id bigint not null generated by default as identity, woche date not null, tag integer not null, spalte text not null, person_id bigint not null, created_at timestamp with time zone default now());
create table public.dienstplan_personen (id bigint not null generated by default as identity, name text not null, farbe text, aktiv boolean not null default true, created_at timestamp with time zone default now());
create table public.disposal (id integer not null generated by default as identity, store_id text, disposal_date date not null default CURRENT_DATE, slot text not null, dish_name text, sold_out_time time without time zone, leftover_qty numeric, note text, updated_at timestamp with time zone default now());
create table public.essen_feedback (id bigint not null generated by default as identity, store_id text not null, datum date not null, name text, ratings jsonb not null default '{}'::jsonb, kommentar text, submitted_at timestamp with time zone default now(), feedback_frei text, bearbeitet boolean default false);
create table public.essen_notruf (id bigint not null generated by default as identity, von_store text not null, an_stores text[] not null default '{}'::text[], erstellt_am timestamp with time zone not null default now(), erledigt boolean not null default false, erledigt_am timestamp with time zone, gerichte text[], mengen jsonb, status text not null default 'offen'::text, absagen text[] not null default '{}'::text[], zusage_von text, zusage_menge text, zusage_am timestamp with time zone, ankunft text, uber_link text, uber_am timestamp with time zone);
create table public.events (id uuid not null default gen_random_uuid(), event_date date not null, title text not null, category text default 'sonstige'::text, color text default '#E94E1B'::text, note text, created_at timestamp with time zone default now());
create table public.feuerloescher (id bigint not null generated by default as identity, standort text not null, anzahl integer not null default 1, letzte_pruefung date, defekt boolean not null default false, notiz text, sort integer not null default 0, created_at timestamp with time zone not null default now());
create table public.forecast_ferien_faktoren (store_id text not null, ferienart text not null, pct numeric not null, basis text, updated_at timestamp with time zone not null default now());
create table public.forecast_qty (id integer not null generated by default as identity, store_id text not null, forecast_date date not null, dish_name text not null, qty numeric not null, source text not null default 'auto'::text, changed_by text, changed_at timestamp with time zone, groesse text default 'gross'::text, eingepackt boolean default false, status text, suggested_qty numeric, change_reason text, confirmed_by text, confirmed_at timestamp with time zone);
create table public.forecast_settings (store_id text not null, weather_sunny_pct numeric not null default 10, weather_rain_pct numeric not null default '-8'::integer, feiertag_pct numeric not null default '-25'::integer, ferien_pct numeric not null default '-10'::integer, updated_at timestamp with time zone default now());
create table public.forecast_suggestion_log (id bigint not null generated by default as identity, store_id text not null, forecast_date date not null, dish_name text not null, category text, suggested_qty numeric, suggestion_reason text, ref_qty numeric, logged_at timestamp with time zone default now());
create table public.freitag_checkliste (id bigint not null generated by default as identity, store_id text not null, datum date not null, items jsonb not null default '{}'::jsonb, erledigt_von text, aktualisiert_am timestamp with time zone not null default now());
create table public.gaeste_feedback (id bigint not null generated by default as identity, ext_id text not null, menu_date date, dish_category text, dish_name text, location text, rating integer, quick_tags text[] default '{}'::text[], reason_other text, comment text, menu_period text, created_at timestamp with time zone, synced_at timestamp with time zone default now());
create table public.geldwechsel (id bigint not null generated by default as identity, store_id text not null, betrag numeric not null, format text not null, status text not null default 'offen'::text, erstellt_am timestamp with time zone not null default now(), erledigt_am timestamp with time zone, detail text);
create table public.gericht_fotos (id bigint not null generated by default as identity, dish_name text not null, foto_url text not null, hinweis text, status text not null default 'test'::text, erstellt_am timestamp with time zone not null default now(), freigegeben_am timestamp with time zone, erstellt_von text);
create table public.grundreinigung_eintraege (id bigint not null generated by default as identity, store_id text not null, datum date not null, durchgefuehrt_von text, items_erledigt jsonb, kontrolle_von text, erstellt_am timestamp with time zone not null default now());
create table public.grundreinigung_items (id bigint not null generated by default as identity, liste text not null, kategorie text not null, text text not null, sort_order integer not null default 0, created_at timestamp with time zone default now());
create table public.guide_eintraege (id bigint not null generated by default as identity, store_id text, kategorie text not null, titel text not null, inhalt text, sort_order integer default 0, erstellt_am timestamp with time zone default now());
create table public.hygiene_ausgeschieden (name text not null, ausgeschieden_am date not null default CURRENT_DATE, markiert_von text, erstellt_am timestamp with time zone not null default now());
create table public.hygiene_notifications (id integer not null generated by default as identity, name text not null, notified_at date not null, created_at timestamp with time zone default now());
create table public.hygiene_schulungen (id integer not null generated by default as identity, name text not null, stores text not null, datum date not null, durchgefuehrt_von text not null, inhalte text not null, created_at timestamp with time zone default now());
create table public.inventur_submissions (id bigint not null generated by default as identity, store_id text not null, submitted_date date not null, submitted_by text, created_at timestamp with time zone not null default now());
create table public.kc_pickup_ready (id bigint not null generated by default as identity, date date not null, store_id text not null, ready_at timestamp with time zone not null default now(), message text);
create table public.kc_stock (id integer not null generated by default as identity, store_id text, article_id integer, ist_bestand numeric not null, updated_date date not null default CURRENT_DATE, created_at timestamp with time zone default now());
create table public.kc_submissions (id bigint not null generated by default as identity, store_id text not null, order_date date not null, submitted_at timestamp with time zone default now());
create table public.kitchen_monitoring (id bigint not null generated by default as identity, datum date not null, lager_kontrolliert boolean default false, reinigung_gemacht boolean default false, wc_gereinigt_von text, temp_kuehlhaus numeric, temp_kuehlschrank_kueche numeric, temp_kuehlschrank_shop numeric, temp_tiefkuehler numeric, submitted_by text, submitted_at timestamp with time zone default now(), lager_details jsonb default '[]'::jsonb, reinigung_details jsonb default '[]'::jsonb, temp_vitrine numeric);
create table public.kitchen_notices (id bigint not null generated by default as identity, datum date not null, icon text not null default '🥡'::text, titel text not null, untertitel text, status text not null default 'aktiv'::text, created_by text, created_at timestamp with time zone not null default now());
create table public.kitchen_supply_baseline (id integer not null generated by default as identity, store_id text not null, weekday integer not null, article_name text not null, unit text not null, base_qty numeric not null);
create table public.kitchen_supply_today (id integer not null generated by default as identity, store_id text not null, supply_date date not null, article_name text not null, qty numeric not null, is_adjusted boolean default false, changed_by text, changed_at timestamp with time zone, kitchen_notified boolean default false, eingepackt boolean default false);
create table public.kuechenlager_verlauf (id bigint not null generated by default as identity, article_id integer not null, stichtag date not null, bestand numeric, zugang numeric default 0, erfasst_am timestamp with time zone default now());
create table public.kuehleinrichtungen (id bigint not null generated by default as identity, store_id text not null, datum date not null, temp_klein numeric, temp_gross numeric, mitarbeiter text, erstellt_am timestamp with time zone default now(), temp_vitrine numeric);
create table public.kunden_feedback (id bigint not null generated by default as identity, store_id text, dish_name text, rating smallint, quick_tags text[] default '{}'::text[], kommentar text, submitted_at timestamp with time zone default now());
create table public.kunden_ohne_essen (id bigint not null generated by default as identity, store_id text not null, datum date not null, anzahl integer not null, uhrzeit time without time zone, created_at timestamp with time zone not null default now(), updated_at timestamp with time zone not null default now());
create table public.maengel (id bigint not null generated by default as identity, store_id text not null, beschreibung text not null, gemeldet_am timestamp with time zone default now(), gemeldet_von text, status text default 'offen'::text, behoben_am timestamp with time zone, behoben_von text, foto_url text, betreff text, verlauf jsonb default '[]'::jsonb, faelligkeit_am date, asana_task_gid text, asana_synced_story_gids text[] default '{}'::text[]);
create table public.menu_check_runs (id bigint not null generated by default as identity, geprueft_am timestamp with time zone not null default now(), sheet_geaendert_am timestamp with time zone, offene_abweichungen integer not null default 0, neue_abweichungen integer not null default 0, hinweis text);
create table public.menu_overrides (id bigint not null generated by default as identity, epoche text not null default 'herbstwinter2026_27'::text, woche integer not null, tag text not null, alt_name text not null, neu_name text not null, gueltig_ab date not null, freigegeben_von text, freigegeben_am timestamp with time zone not null default now(), diff_id bigint);
create table public.menu_sheet_diffs (id bigint not null generated by default as identity, epoche text not null default 'herbstwinter2026_27'::text, woche integer not null, tag text not null, app_name text, sheet_name text, status text not null default 'offen'::text, erkannt_am timestamp with time zone not null default now(), entschieden_am timestamp with time zone, entschieden_von text, hinweis text);
create table public.messe_bewertungen (id bigint not null generated by default as identity, messe_termin_id bigint not null, store_id text not null default '1020'::text, rating integer not null, bewertet_von text, bewertet_am timestamp with time zone default now());
create table public.messe_erfahrung (id bigint not null generated by default as identity, store_id text not null default '1020'::text, name text not null, start_date date not null, end_date date not null, spitzentag date, umsatz integer, ueblich integer, mehr_pct integer, notiz text, quelle text, created_at timestamp with time zone not null default now());
create table public.messe_relevanz (id bigint not null generated by default as identity, messe_termin_id bigint not null, store_id text not null default '1020'::text, notiert_von text, notiert_am timestamp with time zone default now(), einschaetzung text not null);
create table public.messe_termine (id bigint not null generated by default as identity, store_id text not null default '1020'::text, name text not null, start_date date not null, end_date date not null, personen integer, created_at timestamp with time zone default now());
create table public.mitarbeitende (id bigint not null generated by default as identity, store_id text not null, name text not null, eintritt_datum date, ausgeschieden boolean not null default false, ausgeschieden_am date, erstellt_am timestamp with time zone not null default now());
create table public.monthly_cleaning_done (id integer not null generated by default as identity, store_id text not null, month_key text not null, done_at timestamp with time zone default now());
create table public.nachschub_meldungen (id bigint not null generated by default as identity, article_id integer not null, restmenge numeric, gemeldet_von text, status text not null default 'offen'::text, asana_task_gid text, created_at timestamp with time zone not null default now(), bestellt_am timestamp with time zone);
create table public.notstand_meldungen (id bigint not null generated by default as identity, store_id text not null, article_id bigint, produkt text not null, notiz text, status text not null default 'offen'::text, gemeldet_von text, created_at timestamp with time zone not null default now(), erledigt_am timestamp with time zone, menge numeric, benoetigt_bis date);
create table public.order_submissions (id bigint not null generated by default as identity, store_id text not null, order_date date not null, tab text not null, submitted_at timestamp with time zone default now());
create table public.orders (id integer not null generated by default as identity, store_id text, article_id integer, quantity integer not null default 0, order_date date not null default CURRENT_DATE, created_at timestamp with time zone default now(), eingepackt boolean default false);
create table public.org_broadcast_done (id bigint not null generated by default as identity, broadcast_id bigint not null, store_id text not null, created_at timestamp with time zone default now());
create table public.org_broadcast_reads (id integer not null generated by default as identity, broadcast_id integer not null, store_id text not null, read_at timestamp with time zone default now());
create table public.org_broadcast_replies (id integer not null generated by default as identity, broadcast_id integer not null, store_id text not null, reply text, created_at timestamp with time zone default now(), rating smallint);
create table public.org_broadcasts (id integer not null generated by default as identity, message text not null, target_store_id text, created_by text, created_at timestamp with time zone default now(), show_until date, antwort_typ text default 'freitext'::text, photo_url text);
create table public.org_roles (role_key text not null, person_name text not null, label text not null, color text not null);
create table public.org_routine_done (key text not null, period text not null, done_at timestamp with time zone not null default now());
create table public.org_todos (id bigint not null generated by default as identity, text text not null, done boolean not null default false, created_at timestamp with time zone not null default now(), done_at timestamp with time zone);
create table public.page_views (id bigint not null generated by default as identity, view_name text not null, store_id text, created_at timestamp with time zone not null default now());
create table public.produkt_allergene (id bigint not null generated by default as identity, name text not null, category text, allergene_codes text[] default '{}'::text[], aktualisiert_am timestamp with time zone default now());
create table public.rabatt_codes (id bigint not null generated by default as identity, code text not null, wert text, bedingung text not null, stores text[] not null default '{}'::text[], sort_order integer default 0, aktualisiert_am timestamp with time zone not null default now());
create table public.reinigungsprotokoll (id bigint not null generated by default as identity, store_id text not null, datum date not null, reinigung_erledigt boolean default false, desinfektion_erledigt boolean default false, mitarbeiter text, erstellt_am timestamp with time zone default now());
create table public.rezept_zutaten (id bigint not null generated by default as identity, gericht text not null, zutat_id bigint not null, menge text default ''::text, notiz text, erstellt_am timestamp with time zone default now());
create table public.sales_data (id bigint not null generated by default as identity, store_id text not null, sale_date date not null, product_name text not null, quantity numeric, net_amount numeric, imported_at timestamp with time zone default now(), gross_amount numeric);
create table public.sales_history (id integer not null generated by default as identity, store_id text not null, sale_date date not null, dish_category text not null, qty numeric not null, revenue numeric not null default 0);
create table public.samosa_baseline (id integer not null generated by default as identity, store_id text not null, weekday integer not null, base_qty integer not null);
create table public.samosa_erhalten (id bigint not null generated by default as identity, supply_date date not null, qty numeric, updated_at timestamp with time zone default now());
create table public.samosa_lock (id bigint not null generated by default as identity, locked_until_monday date not null, locked_am timestamp with time zone not null default now(), locked_von text);
create table public.samosa_today (id integer not null generated by default as identity, store_id text not null, supply_date date not null, qty integer not null, is_adjusted boolean default true);
create table public.schicht_uebergabe (id bigint not null generated by default as identity, store_id text not null, datum date not null, notiz text, submitted_at timestamp with time zone default now(), gelesen_am timestamp with time zone);
create table public.schrankerl_dish_stats (id bigint not null generated by default as identity, report_id bigint, gericht text not null, zustimmung_pct numeric, positiv integer, negativ integer);
create table public.schrankerl_kommentare (id bigint not null generated by default as identity, gericht text not null, kommentar text not null, sentiment text not null, grund text, datum date);
create table public.schrankerl_menu (id bigint not null generated by default as identity, woche integer not null, slot text not null, name text not null, zutaten text, allergene_codes text[] default '{}'::text[], grammatur text, spezial text);
