create table public.schulungen (id bigint not null generated by default as identity, thema_id bigint, store_id text not null, datum date not null, durchgefuehrt_von text, teilnehmer text, erstellt_am timestamp with time zone default now(), unterschrieben boolean default false);
create table public.schulungsthemen (id bigint not null generated by default as identity, titel text not null, erklaerung text, intervall_monate integer default 12, erstellt_am timestamp with time zone default now());
create table public.special_orders (id integer not null generated by default as identity, store_id text, note text not null, order_date date not null default CURRENT_DATE, created_at timestamp with time zone default now(), antwort text, antwort_am timestamp with time zone, an_simone_gemeldet boolean default false);
