create table public.zutaten_master (id bigint not null generated by default as identity, name text not null, kategorie text not null, allergene_codes text[] default '{}'::text[], image_url text, erstellt_am timestamp with time zone default now(), erstellt_von text, base_zutat_id bigint, variant_label text, normalized_name text, allergene text[] default '{}'::text[], allergene_ungeprueft boolean default false, name_en text);
