-- Check-Constraints
alter table dienstplan_eintraege add check (tag >= 1 and tag <= 5);
alter table events add check (category = any (array['standort','personal','produkt','lieferservice','marketing','sonstige']));
alter table gericht_fotos add check (status = any (array['test','freigegeben']));
alter table grundreinigung_items add check (liste = any (array['standard','kitchen']));
alter table kunden_feedback add check (rating >= 1 and rating <= 5);
alter table kunden_ohne_essen add check (anzahl >= 0 and anzahl <= 500);
alter table menu_overrides add check (tag = any (array['mo','di','mi','do','fr']));
alter table menu_sheet_diffs add check (tag = any (array['mo','di','mi','do','fr','curry','salat','dessert']));
alter table menu_sheet_diffs add check (status = any (array['offen','freigegeben','abgelehnt','erledigt']));
alter table messe_bewertungen add check (rating >= 1 and rating <= 3);
alter table messe_relevanz add check (einschaetzung = any (array['relevant','nicht_relevant','unsicher']));
alter table notstand_meldungen add check (status = any (array['offen','erledigt']));
alter table schrankerl_menu add check (slot = any (array['curry','salat','dessert']));
alter table standing_orders add check (quantity > 0);
alter table standing_orders add check (weekday >= 1 and weekday <= 5);
alter table sweets_nachtraege add check (status = any (array['offen','ja','nein']));

-- Supabase-typische Rollen (PostgREST nutzt anon als Standardrolle)
do $$ begin
  if not exists (select 1 from pg_roles where rolname='anon') then create role anon nologin; end if;
  if not exists (select 1 from pg_roles where rolname='authenticated') then create role authenticated nologin; end if;
  if not exists (select 1 from pg_roles where rolname='service_role') then create role service_role nologin bypassrls; end if;
  if not exists (select 1 from pg_roles where rolname='authenticator') then create role authenticator noinherit login password 'testpw'; end if;
end $$;
grant anon, authenticated, service_role to authenticator;

-- Funktionen (aus Produktiv-DB; check_cron_secret ohne vault, da lokal kein Vault)
create or replace function public.check_store_pin(p_store_id text, p_pin text)
 returns table(id text, name text) language sql security definer set search_path to 'public' as
$$ select s.id, s.name from public.stores s where s.id = p_store_id and s.pin = p_pin; $$;

create or replace function public.check_cron_secret(p text) returns boolean language sql security definer as
$$ select false; $$;

create or replace function public.simple_dish_category(dish text) returns text language plpgsql immutable as $$
begin
  dish := lower(dish);
  if dish ilike '%lasagn%' then return 'Lasagne'; end if;
  if dish ilike '%biryani%' then return 'Biryani'; end if;
  if dish ilike '%dal%' or dish ilike '%dhal%' then return 'Dal'; end if;
  if dish ilike '%curry%' or dish ilike '%gulasch%' or dish ilike '%korma%' or dish ilike '%khadi%' or dish ilike '%masala%' then return 'Curry'; end if;
  if dish ilike '%eatball%' or dish ilike '%köfte%' or dish ilike '%kofte%' then return 'Meatballs'; end if;
  if dish ilike '%bowl%' or dish ilike '%salat%' then return 'Bowl'; end if;
  if dish ilike '%reis%' then return 'Reis'; end if;
  return 'Sonstiges';
end; $$;

-- Rechte + RLS: wie Produktiv, aber einheitlich "anon darf alles", ausgenommen stores.pin (nicht lesbar)
grant usage on schema public to anon, authenticated, service_role;
grant all on all tables in schema public to anon, authenticated, service_role;
grant all on all sequences in schema public to anon, authenticated, service_role;
grant execute on all functions in schema public to anon, authenticated, service_role;

do $$ declare t text; begin
  for t in select tablename from pg_tables where schemaname='public' loop
    execute format('alter table public.%I enable row level security', t);
    execute format('create policy test_all on public.%I for all using (true) with check (true)', t);
  end loop;
end $$;

revoke select on public.stores from anon, authenticated;
grant select (id, name, image_url) on public.stores to anon, authenticated;

